  const ctrlFrom = mid ? { x: 2 * mid.x - (A.x + B.x) / 2, y: 2 * mid.y - (A.y + B.y) / 2 } : null;
  const p0 = A.r ? clipToRect(A.r, ctrlFrom ? ctrlFrom.x : B.x, ctrlFrom ? ctrlFrom.y : B.y) : { x: A.x, y: A.y };
