function renderLines() {
core: {
  const svg = $('#lines'); if (!svg) break core; svg.innerHTML = '';
  const defs = svgEl('defs', {}); svg.append(defs);
  for (const l of linesOf(S.boardId)) {
    const attachedTrashed = [l.from, l.to].some(e => e.cardId && (!ST.cards[e.cardId] || ST.cards[e.cardId].trashed || ST.cards[e.cardId].unsorted));
    if (attachedTrashed) continue;
    const g = lineGeom(l); const col = l.color || 'currentColor';
    const color = l.color || (ST.settings.dark || (board().bg && isDark(board().bg)) ? '#c9ccd0' : '#3b3e42');
    const mk = (id, rev) => { const m = svgEl('marker', { id, viewBox: '0 0 10 10', refX: 8, refY: 5, markerWidth: 5, markerHeight: 5, orient: rev ? 'auto-start-reverse' : 'auto', markerUnits: 'strokeWidth' }); m.append(svgEl('path', { d: 'M0 0L10 5L0 10z', fill: color })); defs.append(m); };
    if (l.startArrow) mk('ms-' + l.id, true);
    if (l.endArrow) mk('me-' + l.id, false);
    const gr = svgEl('g', { 'data-line': l.id });
    gr.append(svgEl('path', { d: g.d, class: 'hit', stroke: 'transparent', 'stroke-width': Math.max(14, (l.weight || 1.5) + 10), fill: 'none' }));
    gr.append(svgEl('path', { d: g.d, stroke: color, 'stroke-width': l.weight || 1.5, fill: 'none', 'stroke-dasharray': l.dashed ? `${(l.weight || 1.5) * 4} ${(l.weight || 1.5) * 3}` : null, 'marker-start': l.startArrow ? `url(#ms-${l.id})` : null, 'marker-end': l.endArrow ? `url(#me-${l.id})` : null, 'stroke-linecap': 'round' }));
    if (l.label) {
      const tw = l.label.length * 6.6 + 14;
      gr.append(svgEl('rect', { x: g.m.x - tw / 2, y: g.m.y - 11, width: tw, height: 22, rx: 3, fill: ST.settings.dark ? '#2a2c2f' : '#ffffff', stroke: color, 'stroke-width': .6, class: 'hit' }));
      const t = svgEl('text', { x: g.m.x, y: g.m.y + 4, 'text-anchor': 'middle', 'font-size': 12, fill: ST.settings.dark ? '#e7e8ea' : '#2b2d30', 'font-family': 'var(--sans)', style: 'pointer-events:none' }); t.textContent = l.label; gr.append(t);
    }
    if (S.selLine === l.id) {
      gr.append(svgEl('path', { d: g.d, stroke: '#2b57ab', 'stroke-width': (l.weight || 1.5) + 3, fill: 'none', opacity: .25, style: 'pointer-events:none' }));
      for (const [k, p] of [['start', g.p0], ['end', g.p1], ['mid', g.m]]) gr.append(svgEl('circle', { cx: p.x, cy: p.y, r: 9, fill: 'transparent', class: 'lh', 'data-lh': k, 'data-lid': l.id })), gr.append(svgEl('circle', { cx: p.x, cy: p.y, r: k === 'mid' ? 2.5 : 3, fill: k === 'mid' ? '#2b57ab' : '#fff', stroke: '#2b57ab', 'stroke-width': 1, class: 'lh', 'data-lh': k, 'data-lid': l.id }));
    }
    svg.append(gr);
  }
  if (S.lineDraft) { const dft = S.lineDraft; svg.append(svgEl('path', { d: `M${dft.x0} ${dft.y0}L${dft.x1} ${dft.y1}`, stroke: '#2b57ab', 'stroke-width': 1.5, 'stroke-dasharray': '5 4', fill: 'none' })); }
}
{ renderMinimap(); }
{ const l = $('#lines'); if (l) l.classList.toggle('raised', !!S.lineDraft); }
}
