  if (![x0, y0, x1, y1].every(isFinite) || x1 - x0 < 1 || y1 - y0 < 1) return;
  const pad = 60, z = clamp(Math.min((r.width - pad * 2) / (x1 - x0), (r.height - pad * 2) / (y1 - y0)), 0.1, 1.5);
