  if (kind === 'line') { checkpoint(); const l = newLine({ x, y: y + 40 }, { x: x + 180, y: y + 40 }); S.sel.clear(); S.selLine = l.id; save(); updateSelUI(); return; }
  if (kind === 'image' || kind === 'upload') { pickFiles(kind === 'image' ? 'image/*' : '', files => addFiles(files, x, y)); return; }
  if (kind === 'draw') { setTool('draw'); return; }
