function addLinkCard(url, x, y) { if (videoInfo(url)) return addVideoCard(url, x, y); checkpoint(); const c = newCard('link', x, y); c.data.url = normUrl(url); c.data.title = hostOf(c.data.url); const yt = ytId(c.data.url); if (yt) c.data.image = `https://img.youtube.com/vi/${yt}/hqdefault.jpg`; S.sel = new Set([c.id]); save(); renderBoard(); fetchPreview(c.id); return c; }
