  if (t.kind === 'list') { moveTask(p.tid, t.list, t.before); return; }
  checkpoint(); f.card.data.items.splice(f.idx, 1); f.card.updatedAt = now();
  let nc;
  if (t.kind === 'canvas') { nc = newCard('todo', t.x - 20, t.y - 14, { title: '', items: [f.item] }); snapCard(nc); }
  else if (t.kind === 'near') { const tc = ST.cards[t.card], r = cardRect(t.card) || { x: tc.x, y: tc.y, w: tc.w, h: 120 }; const pos = freeSpotNear(r, DEF.todo.w, 130, p.row && p.row.closest('.card')); nc = newCard('todo', pos.x, pos.y, { title: '', items: [f.item] }); snapCard(nc); newLine({ cardId: t.card }, { cardId: nc.id }); }
