  if (t.k === 'more') { b.onclick = () => morePop(b); return b; }
  b.addEventListener('pointerdown', e => { if (e.button) return; e.preventDefault(); grabFocus(e.target); P = { type: 'tooldrag', kind: t.k, label: t.label, sx: e.clientX, sy: e.clientY, moved: false }; });
