/* ========== menus ========== */
function buildMenu(items) {
  const m = h('div', { class: 'menu' });
  for (const it of items) {
    if (!it) continue;
    if (it === '-') { m.append(h('div', { class: 'sep' })); continue; }
    if (it.el) { m.append(it.el); continue; }
    if (it.info) { m.append(h('div', { class: 'menu-info' }, it.info)); continue; }
    const row = h('div', { class: 'mi' + (it.disabled ? ' disabled' : '') }, it.dot ? h('span', { style: { width: '14px', height: '14px', borderRadius: '3px', border: '1px solid rgba(0,0,0,.2)', background: it.dot, flex: 'none' } }) : null, it.icon ? h('span', { html: ICON[it.icon] }) : null, h('span', { class: 'lbl' }, it.label), it.check ? h('span', { html: ICON.check, style: { color: 'var(--sel)', width: '14px' } }) : null, it.kbd ? h('span', { class: 'kbd' }, it.kbd) : null, it.sub ? h('span', { class: 'arrow' }, '›') : null);
    if (it.sub) {
      const open = () => {
        $$('.menu.sub').forEach(s => { if (!s.contains(row)) s.remove(); }); $$('.mi.open', m).forEach(x => x.classList.remove('open')); row.classList.add('open');
        const sm = buildMenu(typeof it.sub === 'function' ? it.sub() : it.sub); sm.classList.add('sub'); sm.style.maxHeight = '70vh'; sm.style.overflow = 'auto';
        const r = row.getBoundingClientRect(); document.body.append(sm); placeEl(sm, r.right + 2, r.top - 5);
        if (parseFloat(sm.style.left) < r.right - 4) sm.style.left = Math.max(6, r.left - sm.offsetWidth - 2) + 'px';
      };
      row.addEventListener('mouseenter', open); row.addEventListener('click', open);
    } else {
      row.addEventListener('mouseenter', () => { $$('.menu.sub').forEach(s => { if (!s.contains(row)) s.remove(); }); $$('.mi.open', m).forEach(x => x.classList.remove('open')); });
      row.addEventListener('click', () => { closeTransient(); it.fn(); });
    }
    m.append(row);
  }
  return m;
}
