/* --- lookups and moves --- */
function boardIsLive(bid, depth = 0) { if (bid === ST.rootId) return true; if (depth > 50) return false; const bc = boardCardFor(bid); return !!(bc && !bc.trashed && boardIsLive(bc.boardId, depth + 1)); }
