    const name = boardName(r.bid); svg.append(sEl('text', { x: lw - 8, y: y + 11, class: 'vlab', 'text-anchor': 'end' }, name.length > 16 ? name.slice(0, 15) + '…' : name));
    const segs = [['Urgent', r.u, 'var(--v-urg)'], ['Important', r.i, 'var(--v-imp)'], ['Other', r.o, 'var(--v-oth)']].filter(s => s[1].length);
