  const tog = (label, k, ic) => { const t = h('span', { class: 'toggle' + (st[k] ? ' on' : '') }); return h('label', { class: 'tv-done' + (ic ? ' iconly' : ''), title: label, onclick: () => set(k, !st[k]) }, t, ic ? h('span', { class: 'nv-tic', html: ICON[ic] }) : null, ic ? h('span', { class: 'tv-lab' }, label) : label); };
  const notes = allNotes();
  const q = h('input', { class: 'tv-search', placeholder: 'Search titles, text and file names…', value: st.q });
  q.addEventListener('input', () => { st.q = q.value; renderNVBody(); });
