  let visible = false;
  if (cardEl && !$('.tasksview,.dashview,.docedit')) { const r = cardEl.getBoundingClientRect(); visible = r.right > vr.left + 20 && r.left < vr.right - 20 && r.bottom > vr.top + 20 && r.top < vr.bottom - 20; }
