  const lens = recent.slice(-10).map(s => s.planned).sort((a, b) => a - b); const len = lens.length ? lens[Math.floor(lens.length / 2)] : 30;
  const cnt = {}; for (const s of recent) { const d = new Date(s.start); const k = d.getHours() * 2 + (d.getMinutes() >= 30 ? 1 : 0); cnt[k] = (cnt[k] || 0) + 1; }
