  out.push({ t: 'h', level: Math.min(level, 6), runs: [{ text: (p.icon ? p.icon + ' ' : '') + (p.title || 'Untitled') }] });
  for (const pr of p.schema || []) { const v = propText(pr, p.values[pr.id], p); if (v) out.push({ t: 'p', runs: [{ text: pr.name + ': ', b: 1 }, { text: v }] }); }
