  if (b.type === 'image' && (b.blobId || b.src)) items.push({ label: 'Width', sub: [['sm', 'Small'], ['md', 'Medium'], ['full', 'Full']].map(([k, l]) => ({ label: l, check: (b.width || 'full') === k, fn: () => commitOp(() => { b.width = k; }) })) });
