  const rc = caretRect() || SL.el.getBoundingClientRect(), mh = Math.min(340, SL.menu.scrollHeight + 4);
  const below = rc.bottom + 6 + mh < innerHeight; placeEl(SL.menu, rc.left, below ? rc.bottom + 6 : rc.top - mh - 6);
