  if (k === 'boardemb') { pickBoard(rectAnchor(t), bd => { const g = findBlock(b.id); if (!g) return; commitOp(() => { const n2 = nb('board', '', { boardId: bd.id, h: 320, view: null }); if (isEmptyEl(t) && g.b.type === 'text') g.arr.splice(g.i, 1, n2); else insertBlockAfter(g, n2); }); }); return; }
