  const refresh = () => { save(); renderBoard(); if ($('.tasksview')) { renderTVHead(); renderTVBody(); } $$('.tchip.tag[data-tag="' + id + '"]').forEach(c => { c.style.background = l.color; if (c.firstChild && c.firstChild.nodeType === 3) c.firstChild.textContent = l.name; }); };
  name.addEventListener('change', () => { const v = name.value.trim(); if (!v) { name.value = l.name; return; } touch(); l.name = v; refresh(); });
