const SOON_DAYS = 7;
const quadOf = it => it.important && it.urgent ? 'do' : it.important ? 'schedule' : it.urgent ? 'delegate' : 'later';
const QUADS = { do: ['Do now', 'Urgent + important'], schedule: ['Schedule', 'Important, not urgent'], delegate: ['Delegate', 'Urgent, not important'], later: ['Later', 'Neither flag'] };
const isSoon = (it, t) => !it.done && it.due && it.due <= addDays(t, SOON_DAYS);
const prClass = () => '';

function dashData() {
  const t = todayStr(), all = [], base = [];
  for (const c of taskLists()) for (const it of c.data.items) { normTask(it); all.push({ it, c }); if (taskMatches(it, c, { ignoreDone: true })) base.push({ it, c }); }
  const open = base.filter(x => !x.it.done), done = base.filter(x => x.it.done);
  return { t, all, base, open, done, soon: open.filter(x => isSoon(x.it, t)), imp: open.filter(x => x.it.important), marked: open.filter(x => listMarked(x.c)), allDone: all.filter(x => x.it.done).length };
}
function viewPass(x, st, t) {
  const { it } = x;
  if (st.view === 'done') { if (!it.done) return false; }
  else { if (it.done && !st.showDone) return false; if (st.view === 'marked' && !(listMarked(x.c) && !it.done)) return false; if (st.view === 'important' && !(it.important && !it.done)) return false; if (st.view === 'soon' && !isSoon(it, t)) return false; }
  if (st.quad && (it.done || quadOf(it) !== st.quad)) return false;
  return true;
}

