  const bg = h('div', { class: 'modal-bg', onclick: e => { if (e.target === bg) bg.remove(); } }, h('div', { class: 'modal', style: { padding: '20px', maxWidth: '480px' } }, h('h3', { style: { margin: '0 0 8px' } }, 'Time report'), body, h('div', { style: { marginTop: '12px', textAlign: 'right' } }, h('button', { class: 'btn', onclick: () => bg.remove() }, 'Close'))));
