/* ---- save to a "Frame Reviews" database ---- */
function frSaveDb(b, persist, redraw) {
  const r = b.result; if (!r) return; checkpoint();
  const pg = PE.page; let db = Object.values(ST.dbs).find(d => d && !d.trashed && d.title === 'Frame Reviews'), created = false;
  if (!db) { db = newDb({ t: 'page', id: pg.id }, { title: 'Frame Reviews' }); created = true; }
  const prop = (name, type) => { let p = db.schema.find(x => x.name === name && x.type === type); if (!p) { p = newProp(type, name); db.schema.push(p); } return p; };
  const pDate = prop('Date', 'date'), pOv = prop('Overall', 'number'), pProj = prop('Project', 'text'), pStr = prop('Strongest', 'text'), pWk = prop('Weakest', 'text');
  let row = b.rowId && ST.pages[b.rowId] && !ST.pages[b.rowId].trashed && db.rows.includes(b.rowId) ? ST.pages[b.rowId] : null, isNew = !row;
  if (!row) { row = newRow(db, { title: frTitle(b) || 'Frame review' }); b.rowId = row.id; }
  row.title = frTitle(b) || 'Frame review'; row.values = row.values || {};
  const d = (b.date || '').match(/^\d{4}-\d{2}-\d{2}$/) ? b.date : todayStr();
  row.values[pDate.id] = { start: d }; row.values[pOv.id] = frOverall(b); row.values[pProj.id] = frProject(b); row.values[pStr.id] = r.strongest || ''; row.values[pWk.id] = r.weakest || '';
  for (const s of frScores(b)) { const p = prop(s.c.name, 'number'); row.values[p.id] = s.s; }
  if (isNew) {
    row.blocks = [];
    if (b.blobId) row.blocks.push(nb('image', '', { blobId: b.blobId, width: 'full', caption: '' }));
    row.blocks.push(nb('text', r.verdict ? esc(r.verdict) : ''), nb('text', `<a class="ilink mention" data-ref="p:${pg.id}" contenteditable="false">${esc(pg.title || 'Review page')}</a>`));
  }
  row.updatedAt = now(); db.updatedAt = now();
  if (created) { const f = findBlock(b.id); if (f) { const n2 = nb('db', '', { dbId: db.id, linked: false, views: [], cur: null }); f.arr.splice(f.i + 1, 0, n2); } }
  pg.updatedAt = now(); save(); if (created) renderBody(); else redraw();
  toast(created ? 'Saved to a new “Frame Reviews” database below this block' : (isNew ? 'Added to “Frame Reviews”' : 'Updated in “Frame Reviews”'));
}

