  if (!b || !boardIsLive(b.id)) b = Object.values(ST.boards).find(x => x.id !== ST.rootId && (x.title || '').trim().toLowerCase() === 'journal' && boardIsLive(x.id)) || null;
  if (!b) b = createBoardIn(ST.rootId, 'Journal');
