  const top = top3(), sec = (title, n, ...kids) => h('section', { class: 'ds-panel jn-sec' }, h('div', { class: 'jn-sh' }, h('b', null, title), n != null ? h('span', { class: 'hb-muted' }, String(n)) : null), ...kids);
