        if (rs) { nm = Math.max(15, Math.min(PLAN.to - s0, m0 + dm)); el.style.height = Math.max(18, nm * PLAN.ppm - 2) + 'px'; }
        else { ns = Math.max(PLAN.from, Math.min(PLAN.to - m0, s0 + dm)); el.style.top = (ns - PLAN.from) * PLAN.ppm + 'px'; }
